from openpyxl import load_workbook
wb = load_workbook('output.xlsx', data_only=False)
ws = wb['Compiled and located schools da']
lu = wb['URN lookup']
lupc={}
for r in range(2, lu.max_row+1):
    pc = lu.cell(r,11).value
    if pc is not None:
        pc = str(pc).strip()
        lupc.setdefault(pc, lu.cell(r,4).value)
mismatch=[]
for r in range(2, ws.max_row+1):
    pc = ws.cell(r,12).value
    C = ws.cell(r,3).value
    if C is not None and pc:
        res = lupc.get(str(pc).strip())
        if res != C:
            mismatch.append((r,C,res,str(pc).strip()))
print('num mismatch',len(mismatch))
for row in mismatch[:40]:
    print(row)
"
